    if capacity is None:
        capacity = float("inf")

    coords = get_field(instance, "coords", None)
    if coords is None:
        coords = get_field(instance, "locations", None)
    if coords is None:
        coords = get_field(instance, "nodes", None)

    demands = get_field(instance, "demands", None)
    if demands is None:
        demands = get_field(instance, "demand", None)

    depot_id = 0
    depot_coord = None
    depot = get_field(instance, "depot", None)
    if isinstance(depot, int):
        depot_id = depot
    else:
        depot_coord = to_coord(depot)

    if coords is not None and depot_coord is None:
        if isinstance(coords, dict):
            if depot_id in coords:
                depot_coord = to_coord(coords[depot_id])
        else:
            if 0 <= depot_id < len(coords):
                depot_coord = to_coord(coords[depot_id])

    if depot_coord is None:
        depot_coord = (0.0, 0.0)

    def coord_of(i):
        if isinstance(coords, dict):
            return coords[i]
        return coords[i]

    def demand_of(i):
        if demands is None:
            return 1
        if isinstance(demands, dict):
            return demands.get(i, 1)
        if 0 <= i < len(demands):
            return demands[i]
        return 1

    customer_ids = get_field(instance, "customer_ids", None)
    if customer_ids is None:
        customer_ids = get_field(instance, "customers", None)

    if customer_ids is None:
        if coords is None:
            if isinstance(demands, dict):
                customer_ids = sorted([k for k in demands.keys() if k != depot_id])
            else:
                return []
        else:
            if isinstance(coords, dict):
                customer_ids = sorted([k for k in coords.keys() if k != depot_id])
            else:
                customer_ids = list(range(len(coords)))
                if depot_id in customer_ids:
                    customer_ids.remove(depot_id)

    customer_ids = [i for i in customer_ids if i != depot_id]

    if coords is None:
        customer_ids = sorted(customer_ids)
        routes = []
        cur = []
        load = 0
        for i in customer_ids:
            d = demand_of(i)
            if cur and load + d > capacity:
                routes.append(cur)
                cur = []
                load = 0
            cur.append(i)
            load += d
        if cur:
            routes.append(cur)
        return routes

    items = []
    for i in customer_ids:
        c = coord_of(i)
        cc = to_coord(c)
        if cc is None:
            continue
        dx = cc[0] - depot_coord[0]
        dy = cc[1] - depot_coord[1]
        quad = 0
        if dy >= 0 and dx >= 0:
            quad = 0
            key2 = dy / (abs(dx) + abs(dy) + 1e-12)
        elif dy >= 0 and dx < 0:
            quad = 1
            key2 = abs(dx) / (abs(dx) + abs(dy) + 1e-12)
        elif dy < 0 and dx < 0:
            quad = 2
            key2 = dy / (abs(dx) + abs(dy) + 1e-12)
        else:
            quad = 3
            key2 = abs(dx) / (abs(dx) + abs(dy) + 1e-12)
        items.append((quad, key2, dist(cc, depot_coord), i))

    items.sort()
    ordered = [i for _, _, _, i in items]

    routes = []
    cur = []
    load = 0
    for i in ordered:
        d = demand_of(i)
        if cur and load + d > capacity:
            routes.append(cur)
            cur = []
            load = 0
        cur.append(i)
        load += d
    if cur:
        routes.append(cur)

    def route_load(rt):
        s = 0
        for i in rt:
            s += demand_of(i)
        return s

    def route_cost(rt):
        if not rt:
            return 0.0
        total = 0.0
        prev = depot_coord
        for i in rt:
            total += dist(prev, coord_of(i))
            prev = coord_of(i)
        total += dist(prev, depot_coord)
        return total

    def two_opt(rt):
        n = len(rt)
        if n < 4:
            return rt[:]
        best = rt[:]
        best_cost = route_cost(best)
        improved = True
        while improved:
            improved = False
            n = len(best)
            for a in range(n - 2):
                for b in range(a + 2, n):
                    cand = best[:a + 1] + best[a + 1:b + 1][::-1] + best[b + 1:]
                    c = route_cost(cand)
                    if c + 1e-12 < best_cost:
                        best = cand
                        best_cost = c
                        improved = True
                        break
                if improved:
                    break
        return best

    def insertion_delta(rt, pos, node):
        before = depot_coord if pos == 0 else coord_of(rt[pos - 1])
        after = depot_coord if pos == len(rt) else coord_of(rt[pos])
        nodec = coord_of(node)
        return dist(before, nodec) + dist(nodec, after) - dist(before, after)

    routes = [two_opt(r) for r in routes]

    changed = True
    while changed:
        changed = False
        loads = [route_load(r) for r in routes]
        best_gain = 0.0
        best_move = None

        for a in range(len(routes)):
            ra = routes[a]
            if not ra:
                continue
            for idx, node in enumerate(ra):
                dn = demand_of(node)
                prev = depot_coord if idx == 0 else coord_of(ra[idx - 1])
                nxt = depot_coord if idx == len(ra) - 1 else coord_of(ra[idx + 1])
                rem_delta = dist(prev, nxt) - dist(prev, coord_of(node)) - dist(coord_of(node), nxt)

                for b in range(len(routes)):
                    if a == b:
                        continue
                    if loads[b] + dn > capacity:
                        continue
                    rb = routes[b]
                    best_pos = 0
                    best_ins = None
                    for pos in range(len(rb) + 1):
                        ins = insertion_delta(rb, pos, node)
                        if best_ins is None or ins < best_ins:
                            best_ins = ins
                            best_pos = pos
                    gain = rem_delta - best_ins
                    if gain > best_gain + 1e-12:
                        best_gain = gain
                        best_move = (a, idx, b, best_pos)

        if best_move is not None:
            a, idx, b, pos = best_move
            node = routes[a].pop(idx)
            routes[b].insert(pos, node)
            if not routes[a]:
                routes.pop(a)
            routes = [two_opt(r) for r in routes]
            changed = True

    routes = [r for r in routes if r]
    return routes
